pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // allow the contract's owner (this test contract) to receive ETH via transfer
    receive() external payable {}

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep the funded amount within admissible, transferable bounds
        amount = bound(amount, 1, 1e30);

        // fund the contract directly through its payable fallback
        vm.deal(address(this), amount);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);
        assertEq(address(c).balance, amount);

        // owner (deployer) withdraws everything
        vm.prank(address(this));
        try c.withdrawAll() {
            // GENERAL RULE: after any owner withdrawAll on any admissible balance,
            // the contract's balance is fully drained to zero.
            assertTrue(address(c).balance == 0);
        } catch {
            // a genuine revert would also mean the invariant "withdrawAll always
            // succeeds and drains the balance" is broken; fail explicitly
            assertTrue(address(c).balance == 0);
        }
    }
}

